-- Yemen administrative reference catalog.
-- Source: OCHA Yemen / CSO via HDX, version v01, valid from 2019-11-22,
-- reviewed by the source publisher on 2024-12-23. The import contains
-- 22 first-level administrative units (including Amanat Al Asimah) and 335 districts.
CREATE TABLE "Governorate" (
    "id" TEXT NOT NULL,
    "code" TEXT NOT NULL,
    "nameAr" TEXT NOT NULL,
    "nameEn" TEXT NOT NULL,
    "latitude" DOUBLE PRECISION,
    "longitude" DOUBLE PRECISION,
    "isActive" BOOLEAN NOT NULL DEFAULT true,
    "sortOrder" INTEGER NOT NULL DEFAULT 0,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "Governorate_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "District" (
    "id" TEXT NOT NULL,
    "governorateId" TEXT NOT NULL,
    "code" TEXT NOT NULL,
    "nameAr" TEXT NOT NULL,
    "nameEn" TEXT NOT NULL,
    "latitude" DOUBLE PRECISION,
    "longitude" DOUBLE PRECISION,
    "isActive" BOOLEAN NOT NULL DEFAULT true,
    "sortOrder" INTEGER NOT NULL DEFAULT 0,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "District_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "Governorate_code_key" ON "Governorate"("code");
CREATE INDEX "Governorate_isActive_sortOrder_idx" ON "Governorate"("isActive", "sortOrder");
CREATE UNIQUE INDEX "District_code_key" ON "District"("code");
CREATE UNIQUE INDEX "District_governorateId_nameAr_key" ON "District"("governorateId", "nameAr");
CREATE INDEX "District_governorateId_isActive_sortOrder_idx" ON "District"("governorateId", "isActive", "sortOrder");

ALTER TABLE "District"
ADD CONSTRAINT "District_governorateId_fkey"
FOREIGN KEY ("governorateId") REFERENCES "Governorate"("id")
ON DELETE RESTRICT ON UPDATE CASCADE;

